const guildId = 'YOUR_GUILD_ID'; // Replace with your server's ID (guild ID)
const token = 'YOUR_DISCORD_BOT_TOKEN'; // Replace with your bot's valid Discord bot token
```

3. Implement the ban command as a slash command:
a. First, create an object to define the command:

```javascript
// Define the ban command options
const banCommand = {
  name: 'ban', // Command name
  description: 'Bans a user from the server', // Description shown in the command menu
  options: [
    {
      name: 'user',
      description: 'The user to ban',
      type: 'USER',
      required: true, // Users must provide this option when using the command
    },
    {
      name: 'reason',
      description: 'The reason for the ban (optional)',
      type: 'STRING',
      required: false, // Reason is optional
    },
  ],
};
```

b. Create a function to handle the command execution:

```javascript
async function banInteraction(interaction) {
  const user = interaction.options.getUser('user');
  const reason = interaction.options.getString('reason') || 'No reason specified'; // Default reason if not provided

  // Check if the bot has permission to ban users in the guild
  const hasBanPermission = interaction.guild.members.me.permissions.has("BAN_MEMBERS");
  if (!hasBanPermission) {
    return await interaction.reply({
      content: "I don't have the required permissions to ban users in this server!",
      ephemeral: true, // Replies will be visible only to the user who executed the command
    });
  }

  try {
    // Perform the ban
    await interaction.guild.bans.create({ 
      user: user, 
      reason: reason 
    });

    // Respond with confirmation
    return await interaction.reply(`${user} has been banned from the server for ${reason}.`);
  } catch (error) {
    console.error(error);
    return await interaction.reply({ content: `Error banning ${user}: ${error}`, ephemeral: true });
  }
}
```

4. Register the command with the Discord API:
a. After defining the command and its handler, register the command with Discord:

```javascript
