    std::fstream inputFile("text_file.txt", std::ios::in);
    if (!inputFile) {
        std::cout << "Error opening file." << std::endl;
        return -1;
    }

    // Read each line of the file and update word count
    std::string word;
    while (inputFile >> word) {
        auto found = wordCount.find(word);
        if (found == wordCount.end()) {  // Word not found, initialize count to 1
            wordCount[word] = 1;
        } else {  // Word found, increment existing count
            found->second++;
        }
    }
    inputFile.close();

    // Print word count
    for (const auto& [word, count] : wordCount) {
